570: func startAction(cmd *cobra.Command, args []string) error {
571: 	if exit, err := createStartActionCommon(cmd, args); err != nil {
572: 		return err
573: 	} else if exit {
574: 		return nil
575: 	}
576: 	inst, err := loadOrCreateInstance(cmd, args, false)
577: 	if err != nil {
578: 		return err
579: 	}
580: 	if len(inst.Errors) > 0 {
581: 		return fmt.Errorf("errors inspecting instance: %+v", inst.Errors)
582: 	}
583: 	switch inst.Status {
584: 	case limatype.StatusRunning:
585: 		logrus.Infof("The instance %#q is already running. Run `%s` to open the shell.",
586: 			inst.Name, instance.LimactlShellCmd(inst.Name))
587: 		// Not an error
588: 		return nil
589: 	case limatype.StatusStopped:
590: 		// NOP
591: 	default:
592: 		logrus.Warnf("expected status %#q, got %#q", limatype.StatusStopped, inst.Status)
593: 	}
594: 	ctx := cmd.Context()
595: 	// Network reconciliation will be performed by the process launched by the autostart manager
596: 	if registered, err := autostart.IsRegistered(ctx, inst); err != nil && !errors.Is(err, autostart.ErrNotSupported) {
597: 		return fmt.Errorf("failed to check if the autostart entry for instance %#q is registered: %w", inst.Name, err)
598: 	} else if (registered && autostart.AutoStartedIdentifier() != "") || !registered {
599: 		err = reconcile.Reconcile(ctx, inst.Name)
600: 		if err != nil {
601: 			return err
602: 		}
603: 	}
604: 
605: 	launchHostAgentForeground := false
606: 	if runtime.GOOS != "windows" {
607: 		foreground, err := cmd.Flags().GetBool("foreground")
608: 		if err != nil {
609: 			return err
610: 		}
611: 		launchHostAgentForeground = foreground
612: 	}
613: 	timeout, err := cmd.Flags().GetDuration("timeout")
614: 	if err != nil {
615: 		return err
616: 	}
617: 	if timeout > 0 {
618: 		ctx = instance.WithWatchHostAgentTimeout(ctx, timeout)
619: 	}
620: 
621: 	progress, err := cmd.Flags().GetBool("progress")
622: 	if err != nil {
623: 		return err
624: 	}
625: 
626: 	return instance.Start(ctx, inst, launchHostAgentForeground, progress)
627: }
