151: // StartWithPaths starts the hostagent in the background, which in turn will start the instance.
152: // StartWithPaths will listen to hostagent events and log them to STDOUT until either the instance
153: // is running, or has failed to start.
154: //
155: // The launchHostAgentForeground argument makes the hostagent run in the foreground.
156: // The function will continue to listen and log hostagent events until the instance is
157: // shut down again.
158: //
159: // The showProgress argument tells the hostagent to show provision script progress by tailing cloud-init logs.
160: //
161: // The limactl argument allows the caller to specify the full path of the limactl executable.
162: // The guestAgent argument allows the caller to specify the full path of the guest agent executable.
163: // Inside limactl this function is only called by Start, which passes empty strings for both
164: // limactl and guestAgent, in which case the location of the current executable is used for
165: // limactl and the guest agent is located from the corresponding <prefix>/share/lima directory.
166: //
167: // StartWithPaths calls Prepare by itself, so you do not need to call Prepare manually before calling Start.
168: func StartWithPaths(ctx context.Context, inst *limatype.Instance, launchHostAgentForeground, showProgress bool, limactl, guestAgent string) error {
169: 	haPIDPath := filepath.Join(inst.Dir, filenames.HostAgentPID)
170: 	if _, err := os.Stat(haPIDPath); !errors.Is(err, os.ErrNotExist) {
171: 		return fmt.Errorf("instance %q seems running (hint: remove %q if the instance is not actually running)", inst.Name, haPIDPath)
172: 	}
173: 	logrus.Infof("Starting the instance %q with %s VM driver %q", inst.Name, registry.CheckInternalOrExternal(inst.VMType), inst.VMType)
174: 
175: 	haSockPath := filepath.Join(inst.Dir, filenames.HostAgentSock)
176: 
177: 	prepared, err := Prepare(ctx, inst, guestAgent)
178: 	if err != nil {
179: 		return err
180: 	}
181: 
182: 	if limactl == "" {
183: 		limactl, err = os.Executable()
184: 		if err != nil {
185: 			return err
186: 		}
187: 	}
188: 	haStdoutPath := filepath.Join(inst.Dir, filenames.HostAgentStdoutLog)
189: 	haStderrPath := filepath.Join(inst.Dir, filenames.HostAgentStderrLog)
190: 
191: 	begin := time.Now() // used for logrus propagation
192: 	var haCmd *exec.Cmd
193: 	if isRegisteredToAutoStart, err := autostart.IsRegistered(ctx, inst); err != nil && !errors.Is(err, autostart.ErrNotSupported) {
194: 		return fmt.Errorf("failed to check autostart registration: %w", err)
195: 	} else if !isRegisteredToAutoStart || launchHostAgentForeground {
196: 		if err := os.RemoveAll(haStdoutPath); err != nil {
197: 			return err
198: 		}
199: 		if err := os.RemoveAll(haStderrPath); err != nil {
200: 			return err
201: 		}
202: 		haStdoutW, err := os.Create(haStdoutPath)
203: 		if err != nil {
204: 			return err
205: 		}
206: 		// no defer haStdoutW.Close()
207: 		haStderrW, err := os.Create(haStderrPath)
208: 		if err != nil {
209: 			return err
210: 		}
211: 		// no defer haStderrW.Close()
212: 
213: 		var args []string
214: 		if logrus.GetLevel() >= logrus.DebugLevel {
215: 			args = append(args, "--debug")
216: 		}
217: 		args = append(args,
218: 			"hostagent",
219: 			"--pidfile", haPIDPath,
220: 			"--socket", haSockPath)
221: 		if prepared.Driver.Info(ctx).Features.CanRunGUI {
222: 			args = append(args, "--run-gui")
223: 		}
224: 		if prepared.GuestAgent != "" {
225: 			args = append(args, "--guestagent", prepared.GuestAgent)
226: 		}
227: 		if prepared.NerdctlArchiveCache != "" {
228: 			args = append(args, "--nerdctl-archive", prepared.NerdctlArchiveCache)
229: 		}
230: 		if showProgress {
231: 			args = append(args, "--progress")
232: 		}
233: 		args = append(args, inst.Name)
234: 		haCmd = exec.CommandContext(ctx, limactl, args...)
235: 
236: 		haCmd.SysProcAttr = executil.BackgroundSysProcAttr
237: 
238: 		haCmd.Stdout = haStdoutW
239: 		haCmd.Stderr = haStderrW
240: 
241: 		if launchHostAgentForeground {
242: 			if isRegisteredToAutoStart {
243: 				logrus.Warn("The instance is registered to start at login, but the --foreground option was given, so starting the instance directly")
244: 			}
245: 			haCmd.SysProcAttr = executil.ForegroundSysProcAttr
246: 			if err := execHostAgentForeground(limactl, haCmd); err != nil {
247: 				return err
248: 			}
249: 		} else if err := haCmd.Start(); err != nil {
250: 			return err
251: 		}
252: 	} else if err = autostart.RequestStart(ctx, inst); err != nil {
253: 		return fmt.Errorf("failed to request start via autostart manager: %w", err)
254: 	}
255: 
256: 	if err := waitHostAgentStart(ctx, haPIDPath, haStderrPath); err != nil {
257: 		return err
258: 	}
259: 
260: 	watchErrCh := make(chan error)
261: 	go func() {
262: 		watchErrCh <- watchHostAgentEvents(ctx, inst, haStdoutPath, haStderrPath, begin, showProgress)
263: 		close(watchErrCh)
264: 	}()
265: 	waitErrCh := make(chan error)
266: 	if haCmd != nil {
267: 		go func() {
268: 			waitErrCh <- haCmd.Wait()
269: 			close(waitErrCh)
270: 		}()
271: 	} else {
272: 		defer close(waitErrCh)
273: 	}
274: 
275: 	select {
276: 	case watchErr := <-watchErrCh:
277: 		// watchErr can be nil
278: 		return watchErr
279: 		// leave the hostagent process running
280: 	case waitErr := <-waitErrCh:
281: 		// waitErr should not be nil
282: 		return fmt.Errorf("host agent process has exited: %w", waitErr)
283: 	}
284: }
