290: func waitHostAgentStart(_ context.Context, haPIDPath, haStderrPath string) error {
291: 	begin := time.Now()
292: 	deadlineDuration := 5 * time.Second
293: 	deadline := begin.Add(deadlineDuration)
294: 	for {
295: 		if _, err := os.Stat(haPIDPath); !errors.Is(err, os.ErrNotExist) {
296: 			return nil
297: 		}
298: 		if time.Now().After(deadline) {
299: 			return fmt.Errorf("hostagent (%q) did not start up in %v (hint: see %q)", haPIDPath, deadlineDuration, haStderrPath)
300: 		}
301: 	}
302: }
